#include "autogenerated.h"
#include "uart.h"
#include "tilt_control.h"
#include "maze_core.h"
#include "companion.h"

L298N driver1({
        GPIOA, GPIO_PIN_0,
        GPIOA, GPIO_PIN_1
    }, {
        GPIOA, GPIO_PIN_2,
        GPIOA, GPIO_PIN_3
    }
);

L298N driver2({
        GPIOA, GPIO_PIN_8,
        GPIOA, GPIO_PIN_11
    }, {
        GPIOB, GPIO_PIN_0,
        GPIOB, GPIO_PIN_1
    }
);

TiltController tilt_ctrl(driver1, driver2);

static bool apply_tilt_direction(int direction)
{
    switch (direction) {
    case 0:
        tilt_ctrl.tilt(TiltDirection::DOWN);
        return true;

    case 1:
        tilt_ctrl.tilt(TiltDirection::UP);
        return true;

    case 2:
        tilt_ctrl.tilt(TiltDirection::RIGHT);
        return true;

    case 3:
        tilt_ctrl.tilt(TiltDirection::LEFT);
        return true;

    default:
        tilt_ctrl.stop_all();
        return false;
    }
}

void setup()
{
    hal_setup();

    tilt_ctrl.init();
    tilt_ctrl.lower_all();
    HAL_Delay(3000);
    tilt_ctrl.stop_all();
}

int main()
{
    setup();

    uint32_t seed = 0;

    while(1) {
        int** maze = MazeCore::generate_maze(seed++);
        int* solve_directions = MazeCore::solve_maze(maze);

        int solve_position = 0;

        // Initial state: position 0, with the first required tilt reported.
        transmit_state(
            maze,
            solve_directions,
            seed,
            solve_position,
            HAL_GetTick(),
            0,
            false
        );

        while (solve_directions[solve_position] != -1) {
            const int direction = solve_directions[solve_position];

            if (!apply_tilt_direction(direction)) {
                break;
            }

            // Hold the maze at this tilt for approximately one second.
            HAL_Delay(1000);

            tilt_ctrl.stop_all();

            // The completed tilt advances the ball by one solution step.
            ++solve_position;

            // Report the new position and the next required tilt.
            transmit_state(
                maze,
                solve_directions,
                seed,
                solve_position,
                HAL_GetTick(),
                0,
                false
            );

            // Brief settling time before the next tilt.
            HAL_Delay(100);
        }

        tilt_ctrl.stop_all();
        HAL_Delay(4000);
    }
}